/**
 * Checks a JSON value against ProblemV1, contract version 1: every key and every rule,
 * as the kernel's codec ProblemCodecV1 checks them. Gives the value typed, or the first
 * value that breaks a rule and why.
 */
export function validateProblemV1(value: unknown): Validation<ProblemV1> {
  return validate<ProblemV1>(value, problemV1Rule);
}
